script:
@media (prefers-reduced-motion: no-preference) {
  .proposal-step { transition: opacity .22s ease, transform .22s ease; }
  .proposal-step[hidden] { opacity: 0; transform: translateY(10px); }
  .proposal-back-button { transition: transform .18s ease, background-color .18s ease, border-color .18s ease; }
  .proposal-back-button:hover { transform: translateY(-1px); }
}
@media (prefers-reduced-motion: reduce) {
  .proposal-step, .proposal-back-button { transition: none; }
}
@media (min-width: 360px) and (max-width: 430px) {
  .proposal-step { width: 100%; }
  .proposal-back-button { width: 100%; min-height: 42px; }
  .teacher-groups-section { min-height: 100vh; }
  .corals-signup-section { min-height: 100vh; }
}
